def encode_documents(documents, tokenizer, *, separator='<|endoftext|>'):
    sep = tokenizer.special_tokens[separator]
    if tokenizer.vocab_size > np.iinfo(DTYPE).max + 1:
        raise ValueError('vocabulary does not fit; widen the dtype')
    out = []
    for doc in documents:
        out.extend(tokenizer.encode(doc))
        out.append(sep)
    return np.asarray(out, dtype=np.uint16)
